{
  "name": "Forecast Agent",
  "description": "Synthetic demo agent that forecasts weather.",
  "supportedInterfaces": [
    {
      "url": "https://agent.example.test/a2a",
      "protocolBinding": "JSONRPC",
      "protocolVersion": "1.0"
    }
  ],
  "version": "1.4.0",
  "capabilities": {
    "streaming": true,
    "extensions": [
      {
        "uri": "https://example.test/ext/units",
        "description": "Unit preferences",
        "required": false,
        "params": {
          "defaultUnit": "celsius"
        }
      }
    ]
  },
  "defaultInputModes": [
    "text/plain"
  ],
  "defaultOutputModes": [
    "application/json"
  ],
  "skills": [
    {
      "id": "forecast",
      "name": "Forecast",
      "description": "Forecasts a region.",
      "tags": [
        "weather"
      ]
    },
    {
      "id": "alerts",
      "name": "Alerts",
      "description": "Lists synthetic alerts.",
      "tags": [
        "weather",
        "alerts"
      ]
    }
  ],
  "securitySchemes": {
    "apiKey": {
      "apiKeySecurityScheme": {
        "location": "header",
        "name": "X-Api-Key"
      }
    }
  }
}
